public class CalculatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Operation add = Calculator.add();
        check("add() is not null", true, add != null);
        if (add != null) {
            check("add applies", 7, add.apply(3, 4));
            check("calculate with add", 11, Calculator.calculate(2, 9, add));
        }
        Operation multiply = Calculator.multiply();
        check("multiply() is not null", true, multiply != null);
        if (multiply != null) {
            check("multiply applies", 12, multiply.apply(3, 4));
        }
        check("calculate with custom subtraction", 1, Calculator.calculate(5, 4, (a, b) -> a - b));
        check("calculate with negative result", -8, Calculator.calculate(2, -4, (a, b) -> a * b));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

