interface Operation {
    int apply(int a, int b);
}

public class Calculator {

    public static Operation add() {
        return (a, b) -> a + b;
    }

    public static Operation multiply() {
        return (a, b) -> a * b;
    }

    public static int calculate(int a, int b, Operation op) {
        return op.apply(a, b);
    }
}
